def baseline_report(ergebnis, protocol, karten, fehlerliste):
    fehlt = []
    if not (isinstance(protocol, dict) and protocol.get("metrik")):
        fehlt.append("protokoll-metrik")
    if not (isinstance(karten, dict) and karten.get("datacard") and karten.get("modelcard")):
        fehlt.append("karten")
    if not (isinstance(fehlerliste, list) and any(isinstance(f, dict) and f.get("art") in ("retrieval", "antwort") for f in fehlerliste)):
        fehlt.append("fehlerliste")
    if fehlt:
        return {"status": "verweigert", "fehlt": sorted(fehlt)}
    zaehlung = {art: sum(1 for f in fehlerliste if f.get("art") == art) for art in ("retrieval", "antwort")}
    return {"status": "ok", "metrik": protocol["metrik"], "messwerte": ergebnis["werte"], "fehler_nach_art": zaehlung}

